forever(function () {
    if (mySprite.vx > 100) {
        mySprite.vx = 100
    }
    if (mySprite.isHittingTile(CollisionDirection.Bottom) && controller.A.isPressed()) {
        mySprite.ay = -500
        mySprite.vy = -100
        pause(40)
        timer.background(function () {
            for (let index = 0; index < 36; index++) {
                if (mySprite.isHittingTile(CollisionDirection.Bottom)) {
                    transformSprites.rotateSprite(mySprite, Math.round(transformSprites.getRotation(mySprite) / 90) * 90)
                } else {
                    transformSprites.changeRotation(mySprite, 5)
                    pause(1)
                }
            }
        })
        pause(100)
        mySprite.ay = 500
    }
    if (mySprite.isHittingTile(CollisionDirection.Right)) {
        gameOver()
    }
})
